int dfs(vector<vector<char>>& g, int r, int c) {
    if (g[r][c] != '1' || r < 0 || c < 0 ||
        r >= (int)g.size() || c >= (int)g[0].size())
        return 0;
    g[r][c] = '0';
    return 1 + dfs(g, r + 1, c) + dfs(g, r - 1, c)
             + dfs(g, r, c + 1) + dfs(g, r, c - 1);
}

