from string import ascii_lowercase

def ladder_length(begin, end, words):
    unused = set(words)
    if end not in unused:
        return 0
    unused.discard(begin)
    q = deque([(begin, 1)])               # (word, number of words in the chain so far)
    while q:
        w, steps = q.popleft()
        if w == end:
            return steps
        for i in range(len(w)):
            for ch in ascii_lowercase:
                if ch == w[i]:
                    continue
                nxt = w[:i] + ch + w[i + 1:]
                if nxt in unused:
                    unused.remove(nxt)    # mark visited on discovery
                    q.append((nxt, steps + 1))
    return 0

int minKnightMoves(int x, int y) {
    x = abs(x); y = abs(y);                 // symmetry: solve in the first quadrant
    const int OFF = 2, N = max(x, y) + 3;   // coordinates allowed: [-2, N-1]
    vector<vector<int>> dist(N + OFF, vector<int>(N + OFF, -1));
    const int dx[] = {1, 2, 2, 1, -1, -2, -2, -1};
    const int dy[] = {2, 1, -1, -2, -2, -1, 1, 2};
    queue<pair<int, int>> q;
    q.push({0, 0});
    dist[OFF][OFF] = 0;
    while (!q.empty()) {
        auto [cx, cy] = q.front(); q.pop();
        int d = dist[cx + OFF][cy + OFF];
        if (cx == x && cy == y) return d;
        for (int k = 0; k < 8; ++k) {
            int nx = cx + dx[k], ny = cy + dy[k];
            if (nx < -OFF || ny < -OFF || nx >= N || ny >= N) continue;
            if (dist[nx + OFF][ny + OFF] != -1) continue;
            dist[nx + OFF][ny + OFF] = d + 1;
            q.push({nx, ny});
        }
    }
    return -1;  // not reached: the bounded region always contains a shortest path
}

bool hasPath(vector<vector<int>>& maze, vector<int>& start, vector<int>& dest) {
    int R = maze.size(), C = maze[0].size();
    vector<vector<char>> seen(R, vector<char>(C, 0));
    const int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};
    queue<pair<int, int>> q;
    q.push({start[0], start[1]});
    seen[start[0]][start[1]] = 1;
    while (!q.empty()) {
        auto [r, c] = q.front(); q.pop();
        if (r == dest[0] && c == dest[1]) return true;
        for (int k = 0; k < 4; ++k) {
            int nr = r, nc = c;
            // roll until the next cell is a wall or outside the grid
            while (true) {
                int tr = nr + dr[k], tc = nc + dc[k];
                if (tr < 0 || tr >= R || tc < 0 || tc >= C || maze[tr][tc] == 1) break;
                nr = tr; nc = tc;
            }
            if (!seen[nr][nc]) { seen[nr][nc] = 1; q.push({nr, nc}); }
        }
    }
    return false;
}

void wallsAndGates(vector<vector<int>>& rooms) {
    const int INF = INT_MAX;
    int R = rooms.size(), C = R ? rooms[0].size() : 0;
    queue<pair<int, int>> q;
    for (int r = 0; r < R; ++r)
        for (int c = 0; c < C; ++c)
            if (rooms[r][c] == 0) q.push({r, c});   // all gates are sources
    const int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};
    while (!q.empty()) {
        auto [r, c] = q.front(); q.pop();
        for (int k = 0; k < 4; ++k) {
            int nr = r + dr[k], nc = c + dc[k];
            if (nr < 0 || nr >= R || nc < 0 || nc >= C) continue;
            if (rooms[nr][nc] != INF) continue;      // wall, gate or already set
            rooms[nr][nc] = rooms[r][c] + 1;
            q.push({nr, nc});
        }
    }
}

