from collections import deque

class Node:
    def __init__(self, val, neighbors=None):
        self.val = val
        self.neighbors = neighbors if neighbors is not None else []

def clone_graph(node):
    if node is None:
        return None
    copies = {node: Node(node.val)}       # original -> copy, doubles as visited
    q = deque([node])
    while q:
        cur = q.popleft()
        for nb in cur.neighbors:
            if nb not in copies:
                copies[nb] = Node(nb.val)  # create BEFORE enqueuing, so cycles stop here
                q.append(nb)
            copies[cur].neighbors.append(copies[nb])
    return copies[node]

int shortestPathBinaryMatrix(vector<vector<int>>& g) {
    int n = g.size();
    if (g[0][0] == 1 || g[n - 1][n - 1] == 1) return -1;
    vector<vector<int>> dist(n, vector<int>(n, 0));   // 0 = not visited
    queue<pair<int, int>> q;
    q.push({0, 0});
    dist[0][0] = 1;                                   // path length counts cells
    while (!q.empty()) {
        auto [r, c] = q.front(); q.pop();
        if (r == n - 1 && c == n - 1) return dist[r][c];
        for (int dr = -1; dr <= 1; ++dr)
            for (int dc = -1; dc <= 1; ++dc) {
                int nr = r + dr, nc = c + dc;
                if (nr < 0 || nr >= n || nc < 0 || nc >= n) continue;
                if (g[nr][nc] == 1 || dist[nr][nc]) continue;
                dist[nr][nc] = dist[r][c] + 1;
                q.push({nr, nc});
            }
    }
    return -1;
}

vector<vector<int>> floodFill(vector<vector<int>>& img, int sr, int sc, int color) {
    int old = img[sr][sc];
    if (old == color) return img;            // nothing to do, and avoids an endless loop
    int R = img.size(), C = img[0].size();
    const int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};
    vector<pair<int, int>> st{{sr, sc}};
    img[sr][sc] = color;
    while (!st.empty()) {
        auto [r, c] = st.back(); st.pop_back();
        for (int k = 0; k < 4; ++k) {
            int nr = r + dr[k], nc = c + dc[k];
            if (nr < 0 || nr >= R || nc < 0 || nc >= C || img[nr][nc] != old) continue;
            img[nr][nc] = color;             // the new color doubles as "visited"
            st.push_back({nr, nc});
        }
    }
    return img;
}

void solve(vector<vector<char>>& b) {
    int R = b.size(), C = R ? b[0].size() : 0;
    if (R == 0 || C == 0) return;
    const int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};
    queue<pair<int, int>> q;
    auto seed = [&](int r, int c) {
        if (b[r][c] == 'O') { b[r][c] = '#'; q.push({r, c}); }
    };
    for (int r = 0; r < R; ++r) { seed(r, 0); seed(r, C - 1); }
    for (int c = 0; c < C; ++c) { seed(0, c); seed(R - 1, c); }
    while (!q.empty()) {                       // everything reachable from the border is safe
        auto [r, c] = q.front(); q.pop();
        for (int k = 0; k < 4; ++k) {
            int nr = r + dr[k], nc = c + dc[k];
            if (nr >= 0 && nr < R && nc >= 0 && nc < C) seed(nr, nc);
        }
    }
    for (auto& row : b)
        for (char& ch : row)
            ch = (ch == '#') ? 'O' : 'X';      // safe -> O, surrounded O -> X
}

int largestIsland(vector<vector<int>>& g) {
    int n = g.size();
    const int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};
    vector<int> sz = {0, 0};                 // ids 0/1 are taken by water/land
    for (int r = 0; r < n; ++r)
        for (int c = 0; c < n; ++c) {
            if (g[r][c] != 1) continue;
            int id = sz.size(), cnt = 0;     // label this island with id >= 2
            vector<pair<int, int>> st{{r, c}};
            g[r][c] = id;
            while (!st.empty()) {
                auto [x, y] = st.back(); st.pop_back(); ++cnt;
                for (int k = 0; k < 4; ++k) {
                    int nx = x + dr[k], ny = y + dc[k];
                    if (nx < 0 || nx >= n || ny < 0 || ny >= n || g[nx][ny] != 1) continue;
                    g[nx][ny] = id; st.push_back({nx, ny});
                }
            }
            sz.push_back(cnt);
        }
    int best = 0;
    for (int id = 2; id < (int)sz.size(); ++id) best = max(best, sz[id]);   // no zero to flip
    for (int r = 0; r < n; ++r)
        for (int c = 0; c < n; ++c) {
            if (g[r][c] != 0) continue;
            int ids[4], m = 0, total = 1;
            for (int k = 0; k < 4; ++k) {
                int nx = r + dr[k], ny = c + dc[k];
                if (nx < 0 || nx >= n || ny < 0 || ny >= n || g[nx][ny] < 2) continue;
                int id = g[nx][ny];
                if (find(ids, ids + m, id) != ids + m) continue;   // same island twice
                ids[m++] = id; total += sz[id];
            }
            best = max(best, total);
        }
    return best;
}

int countBattleships(vector<vector<char>>& b) {
    int cnt = 0;
    for (int r = 0; r < (int)b.size(); ++r)
        for (int c = 0; c < (int)b[r].size(); ++c) {
            if (b[r][c] != 'X') continue;
            if (r > 0 && b[r - 1][c] == 'X') continue;   // not the top cell of a vertical ship
            if (c > 0 && b[r][c - 1] == 'X') continue;   // not the left cell of a horizontal ship
            ++cnt;                                       // the "head" of a ship
        }
    return cnt;
}

