int shortestDistance(vector<vector<int>>& g) {
    int R = g.size(), C = g[0].size(), buildings = 0;
    vector<vector<int>> total(R, vector<int>(C, 0)), reach(R, vector<int>(C, 0));
    const int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};
    for (int r = 0; r < R; ++r)
        for (int c = 0; c < C; ++c) {
            if (g[r][c] != 1) continue;
            ++buildings;                       // one BFS per building
            vector<vector<int>> dist(R, vector<int>(C, -1));
            queue<pair<int, int>> q;
            q.push({r, c});
            dist[r][c] = 0;
            while (!q.empty()) {
                auto [x, y] = q.front(); q.pop();
                for (int k = 0; k < 4; ++k) {
                    int nx = x + dr[k], ny = y + dc[k];
                    if (nx < 0 || nx >= R || ny < 0 || ny >= C) continue;
                    if (g[nx][ny] != 0 || dist[nx][ny] != -1) continue;  // walk on empty land only
                    dist[nx][ny] = dist[x][y] + 1;
                    total[nx][ny] += dist[nx][ny];
                    ++reach[nx][ny];
                    q.push({nx, ny});
                }
            }
        }
    int best = INT_MAX;
    for (int r = 0; r < R; ++r)
        for (int c = 0; c < C; ++c)
            if (g[r][c] == 0 && reach[r][c] == buildings) best = min(best, total[r][c]);
    return best == INT_MAX ? -1 : best;
}

