class Solution {
    set<pair<int, int>> seen;                       // relative coordinates, start = (0,0)
    const int dr[4] = {-1, 0, 1, 0};                // up, right, down, left (clockwise)
    const int dc[4] = {0, 1, 0, -1};

    void goBack(Robot& robot) {                     // step back, keep the same facing
        robot.turnRight(); robot.turnRight();
        robot.move();
        robot.turnRight(); robot.turnRight();
    }
    void dfs(Robot& robot, int r, int c, int dir) {
        seen.insert({r, c});
        robot.clean();
        for (int k = 0; k < 4; ++k) {
            int nd = (dir + k) % 4;                 // the robot is facing nd now
            int nr = r + dr[nd], nc = c + dc[nd];
            if (!seen.count({nr, nc}) && robot.move()) {
                dfs(robot, nr, nc, nd);
                goBack(robot);
            }
            robot.turnRight();                      // after 4 turns: original facing
        }
    }
public:
    void cleanRoom(Robot& robot) { dfs(robot, 0, 0, 0); }
