from collections import deque

def snakes_and_ladders(board):
    n = len(board)

    def cell(label):                      # label 1..n*n -> (row, col)
        q, r = divmod(label - 1, n)
        row = n - 1 - q                   # numbering starts at the bottom row
        col = r if q % 2 == 0 else n - 1 - r   # direction alternates every row
        return row, col

    target = n * n
    dist = {1: 0}
    q = deque([1])
    while q:
        cur = q.popleft()
        if cur == target:
            return dist[cur]
        for nxt in range(cur + 1, min(cur + 6, target) + 1):
            r, c = cell(nxt)
            if board[r][c] != -1:
                nxt = board[r][c]          # take it, but only one jump per move
            if nxt not in dist:
                dist[nxt] = dist[cur] + 1
                q.append(nxt)
    return -1

int slidingPuzzle(vector<vector<int>>& board) {
    string s;
    for (auto& row : board) for (int v : row) s += char('0' + v);
    const string target = "123450";
    // neighbors of each index of the 2x3 board, flattened row-major
    const vector<vector<int>> nb = {{1, 3}, {0, 2, 4}, {1, 5}, {0, 4}, {1, 3, 5}, {2, 4}};
    unordered_map<string, int> dist{{s, 0}};
    queue<string> q;
    q.push(s);
    while (!q.empty()) {
        string cur = q.front(); q.pop();
        int d = dist[cur];
        if (cur == target) return d;
        int z = cur.find('0');
        for (int j : nb[z]) {
            string nxt = cur;
            swap(nxt[z], nxt[j]);
            if (dist.count(nxt)) continue;
            dist[nxt] = d + 1;
            q.push(nxt);
        }
    }
    return -1;   // the other parity class: target unreachable
}

def depth_sum(nested):
    total = 0
    stack = [(item, 1) for item in nested]     # explicit stack: no recursion limit
    while stack:
        item, depth = stack.pop()
        if isinstance(item, list):
            stack.extend((x, depth + 1) for x in item)
        else:
            total += item * depth
    return total
